package net.civeira.phylax.feature.access.oauthclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class AudienceVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property audience of oauth client allowed audience ")
  void test_audience_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> AudienceVO.tryFrom(null));
    Assertions.assertEquals("one", AudienceVO.from("one").getAudience());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> AudienceVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", AudienceVO.from("one").toString());
  }
}
